window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-23714eb07f8e58e9"]={"versions": [{"id": "FIG-23714eb07f8e58e9", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Metamodell-Ausschnitt) aus dem AUTOSAR-Standard <code>AUTOSAR_TPS_SecurityExtractTemplate</code>. Das Diagramm spezifiziert die statische Struktur und Vererbungshierarchie des Metamodellelements <code>SecurityEventDefinition</code> im Kontext des Intrusion Detection System (Ids).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen, Beziehungen und Attribute:</p>\n<ul class=\"fig-list\"><li><strong>SecurityEventDefinition</strong>: Konkretes Metamodellelement mit dem Attribut <code>+ id: PositiveInteger [0..1]</code>. Es erbt von <code>IdsCommonElement</code>.\n</li><li><strong>IdsCommonElement</strong>: Abstrakte Basisklasse, spezialisiert <code>ARElement</code>.\n</li><li><strong>ARElement</strong>: Spezialisiert <code>CollectableElement</code> und <code>PackageableElement</code>.\n</li><li><strong>CollectableElement / PackageableElement</strong>: Spezialisiert <code>MultilanguageReferrable</code> und <code>Identifiable</code>.\n</li><li><strong>MultilanguageReferrable / Identifiable</strong>: Enthält über eine Kompositionsbeziehung die Dokumentation <code>+desc</code> mit Kardinalität <code>0..1</code> vom Typ <code>MultiLanguageOverviewParagraph</code>.\n</li><li><strong>SymbolProps</strong> (spezialisiert <code>ImplementationProps</code>): Über eine Kompositionsbeziehung <code>+eventSymbolName</code> mit Kardinalität <code>0..1</code> an <code>SecurityEventDefinition</code> angebunden; versehen mit dem Stereotyp <code>«atpSplitable»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Abläufe, Sequenzen oder Zustandsübergänge zur Laufzeit dar.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>SecurityEventDefinition</code> ist als <code>ARElement</code> bzw. <code>PackageableElement</code> paketierbar in AUTOSAR-ARXML-Modellen.\n</li><li>Die optionale <code>id</code> (<code>PositiveInteger [0..1]</code>) dient der eindeutigen numerischen Identifikation des Security-Events im IDS-Extrakt.\n</li><li>Die Komposition <code>+eventSymbolName</code> (<code>SymbolProps</code>) ermöglicht die Zuordnung eines C-konformen Symbolnamens zur Codegenerierung und ist als <code>«atpSplitable»</code> über mehrere ARXML-Dateien/Teilmodelle hinweg aufteilbar.\n</li><li>Die optionale Beschreibung <code>+desc</code> erlaubt mehrsprachige Dokumentationseinträge auf Basis von <code>MultiLanguageOverviewParagraph</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bd214b8da30009ff", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Metamodell-Ausschnitt) aus dem AUTOSAR-Standard <code>AUTOSAR_TPS_SecurityExtractTemplate</code>. Das Diagramm spezifiziert die statische Struktur und Vererbungshierarchie des Metamodellelements <code>SecurityEventDefinition</code> im Kontext des Intrusion Detection System (Ids).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen, Beziehungen und Attribute:</p>\n<ul class=\"fig-list\"><li><strong>SecurityEventDefinition</strong>: Konkretes Metamodellelement mit dem Attribut <code>+ id: PositiveInteger [0..1]</code>. Es erbt von <code>IdsCommonElement</code>.\n</li><li><strong>IdsCommonElement</strong>: Abstrakte Basisklasse, spezialisiert <code>ARElement</code>.\n</li><li><strong>ARElement</strong>: Spezialisiert <code>CollectableElement</code> und <code>PackageableElement</code>.\n</li><li><strong>CollectableElement / PackageableElement</strong>: Spezialisiert <code>MultilanguageReferrable</code> und <code>Identifiable</code>.\n</li><li><strong>MultilanguageReferrable / Identifiable</strong>: Enthält über eine Kompositionsbeziehung die Dokumentation <code>+desc</code> mit Kardinalität <code>0..1</code> vom Typ <code>MultiLanguageOverviewParagraph</code>.\n</li><li><strong>SymbolProps</strong> (spezialisiert <code>ImplementationProps</code>): Über eine Kompositionsbeziehung <code>+eventSymbolName</code> mit Kardinalität <code>0..1</code> an <code>SecurityEventDefinition</code> angebunden; versehen mit dem Stereotyp <code>«atpSplitable»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Abläufe, Sequenzen oder Zustandsübergänge zur Laufzeit dar.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>SecurityEventDefinition</code> ist als <code>ARElement</code> bzw. <code>PackageableElement</code> paketierbar in AUTOSAR-ARXML-Modellen.\n</li><li>Die optionale <code>id</code> (<code>PositiveInteger [0..1]</code>) dient der eindeutigen numerischen Identifikation des Security-Events im IDS-Extrakt.\n</li><li>Die Komposition <code>+eventSymbolName</code> (<code>SymbolProps</code>) ermöglicht die Zuordnung eines C-konformen Symbolnamens zur Codegenerierung und ist als <code>«atpSplitable»</code> über mehrere ARXML-Dateien/Teilmodelle hinweg aufteilbar.\n</li><li>Die optionale Beschreibung <code>+desc</code> erlaubt mehrsprachige Dokumentationseinträge auf Basis von <code>MultiLanguageOverviewParagraph</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-23714eb07f8e58e9", "to": "FIG-bd214b8da30009ff", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagrammlayout: Die vertikale Vererbungskette (IdsCommonElement -&gt; ARElement -&gt; CollectableElement / PackageableElement -&gt; MultilanguageReferrable / Identifiable) wurde in eine horizontale Anordnung umstrukturiert; MultiLanguageOverviewParagraph ist dadurch unterhalb statt rechts von MultilanguageReferrable platziert.\n</li></ul>"}]};
